using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;
public static class C1Rules{[Serializable]class Row{public string name,status,detail;}[Serializable]class Report{public Row[] rows;}public static void Run(){var rows=new System.Collections.Generic.List<Row>();try{for(int i=0;i<30;i++){var a=RuinsLayout.Generate(3100+i);a.Validate();var b=RuinsLayout.Generate(3100+i);rows.Add(new Row{name="seed-"+i,status=JsonUtility.ToJson(a)==JsonUtility.ToJson(b)&&a.points.Length==RuinsLayout.DefaultStage?"PASS":"FAIL",detail="local deterministic layout"});}var valid=AdventureData.Clone(RuinsLayout.Generate(1));valid.Validate();rows.Add(new Row{name="json-clone-canonical",status="PASS"});var corrupt=AdventureData.Clone(valid);corrupt.terrain.phase=1;bool terrainRejected=false;try{corrupt.Validate();}catch{terrainRejected=true;}rows.Add(new Row{name="noncanonical-forest-terrain-rejected",status=terrainRejected?"PASS":"FAIL"});var x=RuinsLayout.Generate(1);x.mapId="other";bool rejected=false;try{x.Validate();}catch{rejected=true;}rows.Add(new Row{name="unknown-map-rejected",status=rejected?"PASS":"FAIL"});}catch(Exception e){rows.Add(new Row{name="exception",status="FAIL",detail=e.ToString()});}string root=ValidationStorage.Root(Environment.GetCommandLineArgs(),true);File.WriteAllText(root+"/rules.json",JsonUtility.ToJson(new Report{rows=rows.ToArray()},true));EditorApplication.Exit(rows.Any(x=>x.status=="FAIL")?1:0);}}